    "announce.scenes_cta": "Probar Escenas",
    "help.article.scenes.title": "Escenas: generar y editar",
    "help.article.scenes.summary": "Convertí tu video en varias escenas con arco narrativo, y corregí cualquiera.",
    "help.article.scenes.body": "<p><strong>Escenas</strong> convierte tu video en un conjunto de escenas con arco narrativo, en vez de un fondo único repetido toda la canción. El fondo cambia con los momentos del tema y el coro siempre vuelve a su escena.</p><h3>Cómo generarlas</h3><p>En el wizard, en el paso <em>Modo</em>, activá <strong>Escenas</strong>. Funciona con cualquier estilo de movimiento. (Si subís tu propia imagen de fondo, Escenas no aplica — es para fondos generados por IA.)</p><p>Cada video con Escenas consume <strong>3 créditos</strong> (un video normal consume 1).</p><h3>Cómo corregir o regenerar una escena</h3><p>Cuando el video está listo o en revisión, abrí su detalle: vas a ver el <em>filmstrip</em> de escenas. Tocá la que no te gustó y elegí:</p><ul><li><strong>Otra toma</strong> — regenera esa escena con una versión nueva (mismo concepto).</li><li><strong>Editar</strong> — cambiá el prompt o el movimiento de cámara de esa escena.</li></ul><p>Solo la escena que tocaste se regenera; las demás se mantienen. Si la escena es de un coro recurrente, regenerarla cambia todas sus apariciones. Las correcciones de escena <strong>no consumen tu cupo de ediciones</strong>.</p>",
