    // FAQ
    "faq.q1": "¿Cuánto tarda generar un video?",
    "faq.a1": "Menos de 5 minutos por canción, incluyendo transcripción, generación de fondo y render del video.",
    "faq.q2": "¿Puedo editar las lyrics antes de generar?",
    "faq.a2": "Sí. La plataforma transcribe automáticamente y muestra sugerencias de corrección. Podés editar cada línea antes de aprobar.",
    "faq.q3": "¿Los videos son únicos?",
    "faq.a3": "Sí. Cada video tiene un fondo generado por IA basado en la temática de la canción, nunca metraje stock compartido. Por eso no hay riesgo de reclamos de ContentID por clips que otros también usaron.",
    "faq.q4": "¿Puedo subir videos directo a YouTube?",
    "faq.a4": "Sí. La plataforma genera título, descripción y tags optimizados para SEO y los sube directamente al canal conectado.",
    "faq.q5": "¿Quién es dueño del contenido generado?",
    "faq.a5": "El cliente es dueño al 100% de todos los videos, thumbnails y shorts generados. Sin clips de librería compartidos, sin regalías ni atribuciones.",
    "faq.q6": "¿Qué idiomas soporta?",
    "faq.a6": "Español, inglés, portugués, francés, italiano y alemán. Tanto para la transcripción como para la metadata de YouTube.",

