    "announce.control_title": "Your video, under control",
    "announce.control_tagline": "Three new ways to work with precision, without starting over.",
    "announce.control_body": "You now have more control over the lyrics, editing, and background of every video.",
    "announce.control_hl1": "Official lyrics automatically synced to the audio.",
    "announce.control_hl2": "A redesigned editor that keeps the video in view.",
    "announce.control_hl3": "Library backgrounds are now available while editing.",
    "announce.control_f1_title": "Your exact lyrics",
    "announce.control_f1_body": "Paste the official lyrics—no timestamps—and Genly syncs them to the audio.",
    "announce.control_f2_title": "Edit while seeing the result",
    "announce.control_f2_body": "The video and controls share one view, so every change is easier to understand.",
    "announce.control_f3_title": "Change the background, not the project",
    "announce.control_f3_body": "Choose another library background while editing, without regenerating it with AI.",
    "announce.control_cta": "Create a video with more control",
    "announce.motor2_title": "New transcription engine",
    "announce.motor2_tagline": "Better timing, fewer false silences, and a more precise review before render.",
    "announce.motor2_body": "We rebuilt the engine that syncs and transcribes songs: it corrects early entries, filters silence, and keeps each line better aligned.",
    "announce.motor2_hl1": "Segment-aligned timing.",
    "announce.motor2_hl2": "Silences, loops, and unsung text filtered automatically.",
    "announce.motor2_hl3": "More reliable review before generating the video.",
    "announce.motor2_cta": "Create a video",
    "announce.typocase_title": "New Abc style",
    "announce.typocase_tagline": "First letter of each line uppercase, with a more editorial read.",
    "announce.typocase_body": "We added Abc: each line starts with a capital letter and the rest stays lowercase, like a sentence.",
    "announce.typocase_cta": "Try style",
    "announce.cinema_title": "Cinema format",
    "announce.cinema_tagline": "Cinematic black bars for horizontal videos.",
    "announce.cinema_body": "Enable the 2.39:1 look when a release needs a more cinematic frame.",
    "announce.cinema_cta": "Try Cinema",
    "announce.scenes_title": "Scenes: every part of your song, its own film",
    "announce.scenes_tagline": "AI multi-scene — the background changes with the song and the chorus always comes back.",
    "announce.scenes_body": "Instead of a single background, your video is built from several scenes that change with the song and return on the chorus. Turn it on in the Mode step.",
    "announce.scenes_gift": "Launch credits to try it for free.",
    "announce.scenes_hl1": "Several unique scenes, not one background repeated the whole song.",
    "announce.scenes_hl2": "Cuts land on the song's changes: the chorus, the bridge.",
    "announce.scenes_hl3": "The chorus always returns to its scene for visual coherence.",
    "announce.scenes_cost": "Costs {n} credits per video",
    "announce.later": "Later",
    "announce.scenes_cta": "Try Scenes",
    "help.article.scenes.title": "Scenes: generate and edit",
    "help.article.scenes.summary": "Turn your video into several scenes with a narrative arc, and fix any of them.",
    "help.article.scenes.body": "<p><strong>Scenes</strong> turns your video into a set of scenes with a narrative arc, instead of one background repeated the whole song. The background changes with the song's moments and the chorus always returns to its scene.</p><h3>How to generate them</h3><p>In the wizard, on the <em>Mode</em> step, turn on <strong>Scenes</strong>. It works with any motion style. (If you upload your own background image, Scenes doesn't apply — it's for AI-generated backgrounds.)</p><p>Each video with Scenes uses <strong>3 credits</strong> (a normal video uses 1).</p><h3>How to fix or regenerate a scene</h3><p>When the video is ready or in review, open its detail: you'll see the scene <em>filmstrip</em>. Tap the one you don't like and choose:</p><ul><li><strong>Another take</strong> — regenerates that scene with a new version (same concept).</li><li><strong>Edit</strong> — change the prompt or camera motion of that scene.</li></ul><p>Only the scene you tapped is regenerated; the rest stay. If the scene belongs to a recurring chorus, regenerating it changes all its appearances. Scene fixes <strong>don't use your edit quota</strong>.</p>",
