    "help.tip.generic": "More info in the help center.",
    "help.tip.which-format": "MP4 H.264 for web/YouTube; ProRes 422 HQ for broadcast/master. You always get the MP4; ProRes is opt-in.",
    "help.tip.backgrounds": "AI generates one, you pick from the pre-approved library, or upload your own. The library is fastest and safest.",
    "help.tip.style-settings": "Genre + concept + animation set the look. Typography and transition fine-tune the feel. If unsure, keep defaults.",
    "help.tip.manual-sync": "Hit Space when each line starts. The currently selected line gets the live timestamp.",
    "help.tip.approve-from-editor": "Approving from the editor locks timing and triggers the final render. If you'll still tweak lyrics, don't approve yet.",
    "help.tip.job-states": "queued → rendering → pending_review → done. From 'error' you can retry; details show in the panel.",
    "help.tip.prores-master": "Broadcast ProRes 422 HQ master. First export takes 1–2 min; subsequent ones are instant.",
