    "announce.scenes_body": "Em vez de um fundo único, seu vídeo é montado com várias cenas que mudam com a música e voltam no refrão. Ative na etapa de Modo.",
    "announce.scenes_gift": "Créditos de lançamento para experimentar grátis.",
    "announce.scenes_hl1": "Várias cenas únicas, não um fundo repetido a música toda.",
    "announce.scenes_hl2": "Os cortes caem nas mudanças da música: entra o refrão, a ponte.",
    "announce.scenes_hl3": "O refrão sempre volta à sua cena para manter coerência visual.",
    "announce.scenes_cost": "Custa {n} créditos por vídeo",
    "announce.later": "Mais tarde",
    "announce.scenes_cta": "Testar Cenas",
    "help.article.scenes.title": "Cenas: gerar e editar",
    "help.article.scenes.summary": "Transforme seu vídeo em várias cenas com arco narrativo, e corrija qualquer uma.",
    "help.article.scenes.body": "<p><strong>Cenas</strong> transforma seu vídeo em um conjunto de cenas com arco narrativo, em vez de um fundo único repetido a música toda. O fundo muda com os momentos da música e o refrão sempre volta à sua cena.</p><h3>Como gerar</h3><p>No wizard, na etapa <em>Modo</em>, ative <strong>Cenas</strong>. Funciona com qualquer estilo de movimento. (Se você enviar sua própria imagem de fundo, Cenas não se aplica — é para fundos gerados por IA.)</p><p>Cada vídeo com Cenas consome <strong>3 créditos</strong> (um vídeo normal consome 1).</p><h3>Como corrigir ou regenerar uma cena</h3><p>Quando o vídeo está pronto ou em revisão, abra o detalhe: você verá o <em>filmstrip</em> de cenas. Toque na que não gostou e escolha:</p><ul><li><strong>Outra tomada</strong> — regenera essa cena com uma versão nova (mesmo conceito).</li><li><strong>Editar</strong> — mude o prompt ou o movimento de câmera dessa cena.</li></ul><p>Só a cena que você tocou é regenerada; as demais ficam. Se a cena é de um refrão recorrente, regenerá-la muda todas as suas aparições. Correções de cena <strong>não consomem sua cota de edições</strong>.</p>",
