    "edit.background_confirm_desc_imagen": "Gere um novo fundo de foto animado com zoom suave, mantendo as letras e os tempos. Custa ~US$0,03 e leva cerca de 30 segundos. Nenhum risco de rostos humanos em segundo plano. A tipografia atual é mantida.",
